INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hatsune-miku-project-diva-f', 11768, '2012-08-30', 78, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4kws.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mf5fzwisdukyxxl37nnk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hatsune Miku: Project Diva F', 'Hatsune Miku: Project Diva F is a rhythm game and the fifth entry in the Hatsune Miku: Project Diva series of Vocaloid rhythm games. It was also the first game in the Project Diva series to be released in the West. Like the original the game primarily makes use of Vocaloids, a series of singing synthesizer software, and the songs created using these vocaloids, most notably the virtual-diva Hatsune Miku. The game retains the same basic gameplay mechanics from the series albeit with several new changes, most notably the addition of the "Star" symbol to the game''s existing symbols of cross, circle, square, triangle and arrows. The "Star" symbol represents the "Scratch" move where instead of pressing the face buttons as usual, players rub the screen or flick the analogue stick, depending on which system is being used. "Chance Time" has been modified from previous installments, with each successful beat filling a star shaped gauge on the bottom left of the screen. When filled, it triggers a final scratch symbol that, if successfully scored, will change the outcome of the scene. Another new mechanic is the "Technical Zone" mechanic. When it occurs during a song, players must maintain an uninterrupted combo within that time limit for bonus points.' FROM games WHERE igdb_id = 11768 ON CONFLICT (game_id, language_code) DO NOTHING;
