INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zen Pinball 2', 'Zen Pinball 2 launched on PlayStation 4 as a free platform download with a total of 20 tables available as paid DLC. Users can purchase tables inside the Zen Pinball 2 platform, including the following tables and packs at launch: • Star Wars Pinball • Star Wars Pinball: Balance of the Force • Marvel Pinball • Marvel Pinball:Avengers Chronicles • Plants vs. Zombies Pinball • Epic Quest • Paranormal • Earth Defense Zen Studios has HUGE plans for pinball in 2014, including more Star Wars Pinball and Marvel Pinball tables, as well as tables based on more iconic and exciting brands.' FROM games WHERE igdb_id = 6008 ON CONFLICT (game_id, language_code) DO NOTHING;
