INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Euro Truck Simulator 2', 'Euro Truck Simulator 2 is a vehicle simulation game and a direct sequel to the 2008 game Euro Truck Simulator. Travel across Europe as king of the road, a trucker who delivers important cargo across impressive distances! With dozens of cities to explore from the UK, Belgium, Germany, Italy, the Netherlands, Poland, and many more, your endurance, skill and speed will all be pushed to their limits. If you’ve got what it takes to be part of an elite trucking force, get behind the wheel and prove it!' FROM games WHERE igdb_id = 3070 ON CONFLICT (game_id, language_code) DO NOTHING;
