INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-racing-career--1', 253735, '2012-09-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9o2e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3fp9.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Racing Career', 'Start your engines and make your career as a world-class racing driver in one of the most established motorsport management games. Launched in 2012, My Racing Career has grown into a deep, competitive racing sim with a passionate community. From open-wheel racing to stock cars, motorbikes to rally — your path is yours to create. Begin in Formula 4 and work your way up to the big leagues like Formula 1, IndyCar, or Formula E. Or take a different route through touring cars, GT, prototypes, MotoGP, superbikes, or rally series. You control your future. Develop your driver and race strategy in a world where your decisions matter.' FROM games WHERE igdb_id = 253735 ON CONFLICT (game_id, language_code) DO NOTHING;
