INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed III: Liberation', 'Assassin''s Creed III: Liberation is a PlayStation Vita game released on October 30, 2012. Set in 1765 Louisiana, featuring Aveline de Grandpré, a mixed-race female Assassin. The game takes place during the lead-up to the American Revolution, with Aveline navigating the complex social and political landscape of New Orleans. She uses three distinct personas (Assassin, Lady, and Slave) to pursue her missions, fighting against Spanish forces and colonial powers.' FROM games WHERE igdb_id = 3195 ON CONFLICT (game_id, language_code) DO NOTHING;
