INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fable: The Journey', 'Fable: The Journey offers a whole new way to experience the deep storyline and picturesque world of Albion that fans have come to know and love. Set 50 years after the events of Fable III, this new version asks you to come to the aid of the mysterious Theresa, who thrusts you into an action-packed adventure full of dangerous enemies, hair-raising chases and humorous characters. Built from the ground up for Kinect, Fable: The Journey gives you the power to wield magic as a deadly weapon, defend yourself in combat and solve puzzles on your journey to becoming a hero.' FROM games WHERE igdb_id = 1592 ON CONFLICT (game_id, language_code) DO NOTHING;
