INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Max Payne 3', 'Max Payne 3 is a third-person shooter in which the player assumes the role of its titular character, Max Payne. A new feature to the series, introduced in Max Payne 3, is the cover system, which allows players to gain a tactical advantage, and avoid taking damage from enemies. To progress through the linear story, players take on enemies throughout levels. The game features interactive cutscenes which transition seamlessly into continuing gameplay; there are no loading screens across gameplay and cutscenes.' FROM games WHERE igdb_id = 960 ON CONFLICT (game_id, language_code) DO NOTHING;
