INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Amazing Wagon Adventure', 'Super Amazing Wagon Adventure is a fast-paced 2d shooting game with a random story. You control a group of three migrants traveling west along a wagon trail. The game consists of short scenes that are sequenced together in a semi-random way to tell a crazy adventure story. One minute you could be massacring a herd of buffalo, the next attacked by eagles while falling off a cliff.' FROM games WHERE igdb_id = 13100 ON CONFLICT (game_id, language_code) DO NOTHING;
