INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewel Master: Cradle of Egypt 2', 'Cradle of Egypt 2 allows players to journey through 100 levels of challenging match-three fun, all while recreating the millennia-old civilization of Ancient Egypt. Players advance from hard-working farmers to Pharaohs, building the Pyramids, Sphinx and 18 other famous monuments. As part of the best-selling Jewel Master series, Cradle of Egypt 2 builds on the previous games'' formula that has made the series a phenomenal success' FROM games WHERE igdb_id = 23677 ON CONFLICT (game_id, language_code) DO NOTHING;
