INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saturday Morning RPG', 'Saturday Morning RPG is an episodic JRPG set in world heavily inspired by 1980s Saturday morning cartoons and pop culture. Players take the role of Martin "Marty" Michael Hall, an average high-school student who has just been granted an incredible power - a power that ultimately leads him to attract the ire of the world''s most notorious villain, Commander Hood! Saturday Morning RPG features a full soundtrack by legendary composer Vince DiCola (Transformers: The Animated Movie, Rocky IV) and his composing partner, Kenny Meriedeth (contributor for DuckTales, Power Rangers, X-Men, and others).' FROM games WHERE igdb_id = 16840 ON CONFLICT (game_id, language_code) DO NOTHING;
