INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Power Rangers Super Samurai', 'Play Saban''s Power Rangers Super Samurai for Kinect. You''ll be able to morph into a Ranger, play like a Ranger and Train like a Ranger. Co-op play promotes teamwork and Training Mode promotes fitness. Experience multiple levels of difficulty as you defeat the last boss. With each higher level, you will be able to acquire new Weapon Power Ups. Samurai Rangers, Victory is Ours.' FROM games WHERE igdb_id = 25162 ON CONFLICT (game_id, language_code) DO NOTHING;
