INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wreck-It Ralph', 'As a story extension to the highly anticipated upcoming blockbuster film of the same name from Walt Disney Animation Studios, the Wreck-It Ralph video game is set to inspire a whole new generation of young gamers as a classic, arcade-style side scroller featuring Ralph - the misunderstood villain of his own arcade game who sets out to prove he can be a hero too. Debuting this fall tied to the movie release, Wreck-It Ralph will bring all the fun from the big screen right into the living room for the Wii system from Nintendo, and the Nintendo 3DS and Nintendo DS hand-held systems.' FROM games WHERE igdb_id = 23586 ON CONFLICT (game_id, language_code) DO NOTHING;
