INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skullgirls', 'Skullgirls is a fast-paced 2-D fighting game that puts players in control of fierce warriors in an extraordinary Dark Deco world. Featuring all-new game systems which test the skills of veteran fighting game fans while also making the genre enjoyable and accessible to newcomers, Skullgirls is a modern take on classic arcade fighters with a hand-drawn high-definition twist. It’s a one-of-a-kind, action-packed competition complete with awesome combos and an intriguing backstory.' FROM games WHERE igdb_id = 9425 ON CONFLICT (game_id, language_code) DO NOTHING;
