INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hitman: Absolution', 'Hitman: Absolution follows the Original Assassin undertaking his most personal contract to date. Betrayed by the Agency and hunted by the police, Agent 47 finds himself pursuing redemption in a corrupt and twisted world. Showcasing Io-Interactive’s new proprietary Glacier 2 technology, the game has been built from the ground up, boasting a cinematic story, distinctive art direction and highly original game design, Hitman Absolution combines much loved classic gameplay with completely new gameplay features for the Hitman franchise.' FROM games WHERE igdb_id = 530 ON CONFLICT (game_id, language_code) DO NOTHING;
