INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Middens', 'Middens is a surrealist RPG that lets players explore a world full of strange denizens and scenery. The art style is a mixture of collage, traditional drawing and pixel art that gives the game a very unique atmosphere. The game is non-linear.' FROM games WHERE igdb_id = 55004 ON CONFLICT (game_id, language_code) DO NOTHING;
