INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fractured Soul', 'Fractured Soul takes the classic platformers of the 80s and doubles the action! Your unique ability to shift between two parallel dimensions allows you to weave through enemy fire, catch opponents by surprise, and leap over impossibly wide gaps by using platforms in both realities.' FROM games WHERE igdb_id = 8261 ON CONFLICT (game_id, language_code) DO NOTHING;
