INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caveman Craig 2: The Tribes of Boggdrop', 'A unique strategy/RTS game set in a prehistoric world of dinosaurs and cavemen. Play as Craig and decide the fate of man as you hunt, gather, and prepare your way to victory! Demonstrate new skills to your cavemen so they can contribute to the survival of your people!' FROM games WHERE igdb_id = 24045 ON CONFLICT (game_id, language_code) DO NOTHING;
