INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-denpa-men-they-came-by-wave', 9662, '2012-02-08', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wgw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hzt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Denpa Men: They Came By Wave', 'A dungeon crawler with nods to Pikmin, Dragon Quest and Pokemon. Use the 3DS camera to capture Denpa Men to build your party. Mysterious little creatures float around near the waves. They''re called "Denpa" Men. You can''t see them normally, but you can find them and catch them with your Nintendo 3DS. This is a role-playing game in which you collect Denpa Men to form a party, and use this party to explore dungeons. Each radio wave territory has its own completely unique Denpa Men, and no two of them are ever the same! Their faces, bodies, and personalities are all different, and some of them even have special skills and strong points.' FROM games WHERE igdb_id = 9662 ON CONFLICT (game_id, language_code) DO NOTHING;
