INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Last Stand: Dead Zone', 'The Last Stand: Dead Zone is a multiplayer survival RPG where players manage a compound of survivors during a zombie apocalypse. Players lead teams on real-time scavenging missions across an infected city, collecting resources and equipment from over 30,000 available items. The game combines base-building mechanics with strategic combat, allowing players to fortify their settlement, assign specialized roles to survivors, and craft equipment from gathered materials. Players can join alliances and interact with others through cooperative building or competitive raiding for resources.' FROM games WHERE igdb_id = 59516 ON CONFLICT (game_id, language_code) DO NOTHING;
