INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('highway-rider', 86999, '2012-05-09', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/mdekpxl0kcafoadof6vk.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/stxsw1xg1jrbwxjepxtb.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Highway Rider', 'Highway Rider is a free and exciting motorcycle racer that lets you dodge traffic with blazing fast speed and zoom down a busy highway, passing by cars and semis, and building up your points to become the best there is! Escape the flashing blue lights of the police by speeding through traffic barriers and narrowly avoiding collisions. Collect tons of unlockable racers, share photos and videos of your collisions with other racers, and customize your bike in this high speed motorcycle action game.  FEATURES: Extreme Racing > Dart and dodge traffic while trying to get the high score with close calls between cars and trucks! > Use boosts to go faster and increase your scores on 4 different highways. > Customize Your Bike > Customize your motorcycle and give your racers their own unique style! > Unlock all 10 characters with their own motorcycles and outfits! Real-time Multiplayer Races > Battle other racers in head-to-head racing games and other multiplayer games. > Share your spectacular crashes and wipeouts with all of your friends! > Complete online racing challenges and unlock achievements! Fugitive Mode > Outrun the cops and break through police barricades in this furious game of cat and mouse! Speed junkies, slap on your motorcycle helmets and experience some high-octane racing! Zoom down the open roads and try not to crash! Highway Rider is the ultimate racing game for any motorcycle fan! Comment below your feature requests and favorite features! We will continue to update the app with more content and features. Follow us at @batteryacidapps or the creator at @derekarndt' FROM games WHERE igdb_id = 86999 ON CONFLICT (game_id, language_code) DO NOTHING;
