INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Political Machine 2012', 'Do you have what it takes to be president? Play as more than 20 candidates including Barack Obama, Mitt Romney, Rick Santorum, Ron Paul, Newt Gingrich or create your own candidate from scratch. Players take to the campaign trail against a computer controlled opponent or a human challenger over the Internet. The goal: win the hearts and minds of America''s voters to achieve victory in the 2012 presidential election.' FROM games WHERE igdb_id = 51349 ON CONFLICT (game_id, language_code) DO NOTHING;
