INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Killzone HD', 'Killzone HD is a remastered version of the 2004 PS2 Killzone game, made for inclusion in Killzone Trilogy Collection, but also offered standalone as a PSN download. It is a reworked version of the original game with 720p graphics at 30fps, MSAA filtering, sharper textures, higher quality sound effects, and trophy support.' FROM games WHERE igdb_id = 20003 ON CONFLICT (game_id, language_code) DO NOTHING;
