INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Park: Builder', 'Jurassic Park: Builder was an Apple and later Android and Facebook application produced by Ludia in 2012. It was a construction and management simulation game in which the player built a Jurassic Park featuring extinct animals. It coincided with the release of Jurassic Park 3D and was considered a mobile counterpart to Jurassic Park III: Park Builder and Jurassic Park: Operation Genesis. Three kinds of parks were available. Jurassic Park, located on Isla Nublar, featuring dinosaurs and other Mesozoic animals. Aquatic Park, located on a seabed featuring extinct aquatic animals. Glacier Park, located in Patagonia, featuring extinct animals from the Cenozoic era along with some Mesozoic crocodilians.' FROM games WHERE igdb_id = 10531 ON CONFLICT (game_id, language_code) DO NOTHING;
