INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Joe Danger 2: The Movie', 'Joe Danger, the world’s most determined stuntman, returns to embark on a death-defying thrill-ride across the set of the greatest blockbuster movie ever made. Across 100 crazy levels he’ll chase crooks by police bike, destroy laser-firing robots with a stolen jetpack, escape giant boulders in a minecart, time-travel to punch dinosaurs from a quad bike and divert nuclear missiles on a unicycle. Strap on the helmet of Joe Danger, impress the director and make action movie history!' FROM games WHERE igdb_id = 11241 ON CONFLICT (game_id, language_code) DO NOTHING;
