INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Little Inferno', 'Congratulations on your new Little Inferno Entertainment Fireplace! Throw your toys into your fire, and play with them as they burn. Stay warm in there. It''s getting cold outside! Burn flaming logs, screaming robots, credit cards, batteries, exploding fish, unstable nuclear devices, and tiny galaxies. An adventure that takes place almost entirely in front of a fireplace - about looking up up up out of the chimney, and the cold world just on the other side of the wall.' FROM games WHERE igdb_id = 1363 ON CONFLICT (game_id, language_code) DO NOTHING;
