INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('saints-row-the-third-the-full-package', 25268, '2012-11-06', 58, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8klz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbcx.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saints Row: The Third - The Full Package', 'Features From the ingenious minds that brought you all those Saints Row games comes the ultimate Saints Row compilation. THQ and Volition, Inc. proudly present Saints Row: The Third – The Full Package. This premier edition includes award-winning Saints Row: The Third, all three downloadable mission packs, and more than 30 bonus DLC items. With every weapon, every vehicle, every outfit, go over the top, off the reservation, and to places where no decent game should go. Strap it on, all the way. INCLUDES MORE THAN $50 IN BONUS CONTENT* Three mission packs and more than 30 bonus DLC items from such hits as the Shark Attack pack, Witches & Wieners pack, and the Genki Girl Vehicle pack. This is the definitive Saints Row: The Third experience.' FROM games WHERE igdb_id = 25268 ON CONFLICT (game_id, language_code) DO NOTHING;
