INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bus-simulator-2012', 16700, '2012-02-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3mo9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arrn3.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bus-Simulator 2012', 'Catch the bus and let it take you to a detailed, virtual world. Every technical detail of the original bus has been reproduced true-to-live. Switch on the air-conditioning when your front-shields are steaming up and keep an eye on the speedograph, to stay in schedule – even though you have a lot of missions, you will still need to rest in order to stay fit! Thanks to the digital readouts in the bus, you can monitor your engine’s temperature and the charging level of the cooling liquid as well as the oil and gasoline level.' FROM games WHERE igdb_id = 16700 ON CONFLICT (game_id, language_code) DO NOTHING;
