INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sonic the Hedgehog 4: Episode II', 'The Sonic 4 Saga continues in Episode II with the return of a beloved side kick and fan-favorite villains! Following the events of Episode I, Metal Sonic has returned to form an alliance with Dr. Eggman! To face this new evil, Sonic will have to call upon an old friend to help him save the day!' FROM games WHERE igdb_id = 9474 ON CONFLICT (game_id, language_code) DO NOTHING;
