INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Stable', 'Star Stable Online is a MMORPG built for those with a passion for horses and games. It is a modern continuation and expansion of the story told in the single-player CD-ROM PC Starshine Legacy series and the Star Stable Season Riders series. Players are immersed in the magical world of Jorvik, an island known for it''s passion for horses, they say that riders on Jorvik can bond with their horse deeper than anywhere else in the world. They can ride and explore, customize their character, buy horses, compete in different races and competitions, chat and hang out with other players, and uncover the game''s rich story and lore in the main quests.' FROM games WHERE igdb_id = 60338 ON CONFLICT (game_id, language_code) DO NOTHING;
