INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ōkami HD', 'Experience the critically acclaimed masterpiece with its renowned Sumi-e ink art style in breathtaking high resolution. Take on the role of Amaterasu, the Japanese sun goddess who inhabits the form of a legendary white wolf, on a quest to defeat Orochi, an eight-headed demon and tyrannical monster responsible for turning the world of Nippon into a ruined wasteland.' FROM games WHERE igdb_id = 20744 ON CONFLICT (game_id, language_code) DO NOTHING;
