INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdoms of Amalur: Reckoning', 'Kingdoms of Amalur: Reckoning is an epic, open-world role-playing game set in Amalur, a mysterious and magical new fantasy world created by New York Times best-selling author R. A. Salvatore. Brought to life visually through the trademark visceral style of renowned artist and Spawn creator Todd McFarlane, Reckoning brings a new level of intense action combat to the RPG genre.' FROM games WHERE igdb_id = 1059 ON CONFLICT (game_id, language_code) DO NOTHING;
