INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('interlocked', 83578, '2012-10-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co81ht.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yaixbkpvs68zldn9hujr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Interlocked', 'Have you ever seen those masterfully crafted wooden block puzzles? The ones that look so simple, yet prove such a challenge to pull apart? Interlocked serves up cleverly crafted 3D puzzles where the goal is to figure out how each interlocking level fits together in order to pull it apart. With simple, intuitive, touch-based gameplay and five beautifully crafted chapters, Interlocked will delight puzzles fans of all skill levels, completely free. - 3D brain-teasing puzzles - 5 challenging chapters to beat - Brought to you by the creators of the original Flash game, played by over 20 million! - Many achievements to unlock This port of Interlocked adds four new level packs.' FROM games WHERE igdb_id = 83578 ON CONFLICT (game_id, language_code) DO NOTHING;
