INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cypher-cyberpunk-text-adventure', 64616, '2012-08-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x994vwyliivh6opufuk4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5rvk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cypher: Cyberpunk Text Adventure', 'Cyberpunk interactive fiction video game written by the Cabrera Brothers and released on August 31, 2012. It updates the traditional text adventure format by including music, sound effects and limited graphical elements to the game. The game is available as a download for Microsoft Windows and Macintosh OS X, purchasable directly from the creators'' website. Gameplay consists of the player reading descriptions of their character''s location and surroundings as presented in text form by the game, then inputting their desired actions into the text parser. Further atmospheric detail is provided throughout the game in the form of background music and sound effects, as well as an animated image of the player character on the righthand side of the screen. When the player collects an important object from the game environment, these too are displayed on the right hand side. These images are updated when the object changes, such as when a dirty keycard is cleaned or a device is activated.' FROM games WHERE igdb_id = 64616 ON CONFLICT (game_id, language_code) DO NOTHING;
