INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papo & Yo', 'A semi-autobiographical 3D puzzle platformer in which a boy named Quico is transported from his abusive home into a dreamlike favela where he has to lead an easygoing creature named Monster through the world with the help of his sister and Lula, his robotic doll, while protecting himself and his companions from Monster''s frenzy fits brought on by an addiction to poison frogs.' FROM games WHERE igdb_id = 7388 ON CONFLICT (game_id, language_code) DO NOTHING;
