INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fray-reloaded-edition', 16364, '2012-05-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/qqgdximlw5va7onoao2r.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qaz3rhvbvwuo6mk6eeuh.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fray: Reloaded Edition', 'Fray: Reloaded Edition is a fully simultaneous, turn-based multiplayer strategy game. Set in a dystopian future in the year 2098 where human interaction is confined to virtual reality modules, three mega-corporations vie for control of Earth. Within the combat module, Fray, pledge allegiance to one of the corporations and take control of a squad of four soldiers from six classes with unique weapons and abilities. Choose your squad wisely, assign actions and when the turn timer is up, watch the action play out in real-time cinematic fashion.' FROM games WHERE igdb_id = 16364 ON CONFLICT (game_id, language_code) DO NOTHING;
