INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Little Pony: Magic Princess', 'Saddle up for adventure with Twilight Sparkle & friends! After being locked away in the moon for centuries, Nightmare Moon is set free and spreading night across Ponyville! Only Twilight Sparkle and her friends can free Ponyville from her grasp and bring light and friendship back to the land. Help them rebuild the town and reach their dreams in exciting quests!' FROM games WHERE igdb_id = 86783 ON CONFLICT (game_id, language_code) DO NOTHING;
