INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bleed', 'Wryn is a girl with a big arsenal and big dreams and she wants to be the ultimate videogame hero! Help her take down the Greatest Heroes of All Time in an action-packed bid to claim the title for herself and show the world what a true hero looks like! Bleed is an action-platformer focused on stylish, acrobatic dodging and fluid, challenging gameplay. There''s no filler, just you and your skills against seven levels of enemies, obstacles, breakneck set-pieces and inventive bosses.' FROM games WHERE igdb_id = 9706 ON CONFLICT (game_id, language_code) DO NOTHING;
