INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wonderbook: Book of Spells', 'Book of Spells (or Wonderbook: Book of Spells) is an augmented reality video game developed in conjunction with J. K. Rowling as a companion to the Harry Potter series. It was introduced at the Electronic Entertainment Expo in June 2012 and is the first release for the Wonderbook. It is based on Book of Spells, a fictional book by Miranda Goshawk released about 200 years from the event date.' FROM games WHERE igdb_id = 22191 ON CONFLICT (game_id, language_code) DO NOTHING;
