INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ace of Spades: Battle Builder', 'Say hello to the creative shooter. Ace of Spades: Battle Builder is the first-person shooter that lets you create your battleground, destroy it, then create it again. Up to 32 players choose from seven unique classes and jump into team-based, multiplayer mayhem across an endlessly evolving battlefield, to construct, destruct and take out the opposition.' FROM games WHERE igdb_id = 23400 ON CONFLICT (game_id, language_code) DO NOTHING;
