INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('capsule', 17487, '2012-02-14', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co80fq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1ibv.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Capsule', 'Capsule is a single-player survival game played entirely through a radar interface. Players navigate a hostile landscape, learn about their surroundings, and unravel a classic sci-fi story in the process. Best played in a dark room with headphones. In a strange and hostile place, something has gone very, very wrong. You wake up inside a small capsule, trapped, with no view of the outside world. The only way to survive is to use the radar screen and the capsule''s simple controls to try and find more oxygen and more fuel... and to find out what happened. Capsule is a short game, approximately 2 hours for most players. Capsule is not a game for everyone; if you are claustrophobic, misophonic, and/or have anxiety or triggers related to asphyxiation and/or darkness Capsule may not be a good game for you.' FROM games WHERE igdb_id = 17487 ON CONFLICT (game_id, language_code) DO NOTHING;
