INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spelunky', 'Spelunky (also known as Spelunky HD) is a remake of Spelunky (now known as Spelunky Classic), an open source indie platformer video game created by Derek Yu and originally released as freeware for Microsoft Windows. The player controls a spelunker who explores a series of caves while collecting treasure, saving damsels, fighting enemies and dodging traps. The caves are procedurally generated, making each run through the game unique. Spelunky is one of the first examples of a roguelike-like, borrowing concepts from the roguelike genre, and was the influence for many later roguelike-like games.' FROM games WHERE igdb_id = 3029 ON CONFLICT (game_id, language_code) DO NOTHING;
