INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'New Super Mario Bros. 2', 'New Super Mario Bros. 2 is a side-scrolling 2.5D action-adventure platform game for the Nintendo 3DS. As the direct sequel to New Super Mario Bros., it is an indirect follow-up to New Super Mario Bros. Wii. The game''s main focus is on coins, with the primary goal being to collect one million. To reach the goal, the game includes many new items to aid the player, such as the Gold Flower, which turns Mario into Gold Mario.' FROM games WHERE igdb_id = 1080 ON CONFLICT (game_id, language_code) DO NOTHING;
