INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pitfall--1', 19908, '2012-08-09', 60, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9k2s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scvsqz.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pitfall!', 'Pitfall! for iOS/Android, reimagined as an infinite runner! Let me introduce myself. I''m Pitfall Harry, veteran jungle explorer. Fortune hunting''s my game, and yours, too, if you''re daring enough to take this trip with me. Don''t be nervous; I''ll be your guide through the jungle, and I''m one of the best. Untold riches are waiting for us in there, but so are dangers a dozen times over. We''ll be swinging on vines over bottomless tarpits. We''ll be hopping across swamps, using crocodile heads like stepping stones. We''ll be searching underground through dark passageways crawling with killer scorpions. So pack up your backpack and meet me at the jungle at dawn - and we''ll be off to seek a king''s ransom in gold, diamonds and lost treasures - in Pitfall Harry''s Jungle Adventure.' FROM games WHERE igdb_id = 19908 ON CONFLICT (game_id, language_code) DO NOTHING;
