INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angry Birds Space', 'Play over 300 interstellar levels across 10 planets! Whether it’s the icy orbs of Cold Cuts, the volcanic explosiveness of Red Planet, Utopia – a planet made entirely of junk food, or the new Brass Hogs episode ruled by evil Hektor Porko, each episode offers intergalactic fun at every turn! And the low-gravity environment of space results in spectacular gameplay ranging from slow-motion puzzles to lightspeed destruction. With brand new birds, special abilities, and a whole galaxy to explore, the sky is no longer the limit!' FROM games WHERE igdb_id = 16365 ON CONFLICT (game_id, language_code) DO NOTHING;
