INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Zero 2: Wii Edition', 'Fatal Frame 2: Wii Edition is a remake Fatal Frame II: Crimson Butterfly, originally for the PlayStation 2 and the Xbox. Deep Crimson Butterfly features several major gameplay improvements and enhancements that the original doesn''t have such as: -A dynamic over the shoulder third person camera angle first used in Mask of the Lunar Eclipse. -The map and layout of the game have been updated to work better with the new viewpoint. -The graphics and character models are vastly improved, and the costumes were designed with more emphasis on the back since it is constantly in the player''s view.' FROM games WHERE igdb_id = 14409 ON CONFLICT (game_id, language_code) DO NOTHING;
