INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sine-mora', 10832, '2012-03-21', 85, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co20fi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arnou.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sine Mora', 'Sine Mora is a horizontal shoot''em up that provides a unique take on challenge, where time is the ultimate factor. Mixing classic shooter sensibilities with contemporary presentation, Sine Mora is a gorgeous shmup that offers a Story Mode that weaves an over-the-top tale and an Arcade Mode that provides deep, satisfying gameplay to challenge fans of the genre. With many ways to manipulate time, Sine Mora features over 50 weapon combinations to complete each beautiful stage that form fits to the player''s skills with scaling difficulty. Soundtrack composed by Akira Yamaoka and featuring boss designs by Mahiro Maeda.' FROM games WHERE igdb_id = 10832 ON CONFLICT (game_id, language_code) DO NOTHING;
