INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('007-legends', 1649, '2012-10-16', 46, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co203u.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/hg1nv69lbuzonkenmuwg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '007 Legends', '007 Legends features an original, overarching storyline tying together six classic Bond movies for an original James Bond experience, and equips players with state-of-the-art spy gadgets, an arsenal of weapons and more. In addition to 007 Legends'' main story, the game features the return of fan-favorite single-player Mi6 Ops Missions, which debuted in GoldenEye 007: Reloaded and challenges players to complete extra missions ranging from all-out action to stealth and gadget-based gameplay and compete for the highest online leader board scores. Also for the first time ever, players will be able to participate as one of Bond''s cohorts or villainous foes, reliving the missions through their eyes, as well as 007''s. Meanwhile the robust James Bond multiplayer experience includes local four-player split-screen game modes and online competitive gameplay with new maps, weapons and characters derived from Bond''s 50 year legacy. With more gadgets, deeper stealth and spy investigation gameplay, gamers will have every opportunity to truly feel like the world''s favorite spy.' FROM games WHERE igdb_id = 1649 ON CONFLICT (game_id, language_code) DO NOTHING;
