INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Into the Dead', 'In a world overrun with the Dead, you have survived… but for how long? In a world overrun with the Dead, you have survived… but for how long? Into the Dead throws you into the gruesome world of the zombie apocalypse where there are no second chances. Do what you have to in order to stay alive, keep moving as fast as you can, and protect yourself by any means necessary. When the Dead are rising, run!' FROM games WHERE igdb_id = 20911 ON CONFLICT (game_id, language_code) DO NOTHING;
