INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Guns of Icarus Online', 'Guns of Icarus Online is a team-based multiplayer online airship combat game. Captain or serve as crew aboard an airship with your friends and fly into battle against other ships in a steam/dieselpunk-inspired, post-apocalyptic world. Each player takes on one of the three roles aboard the ship—Captain, Gunner, or Engineer—and must work together to take down enemies and keep the ship flying. The game is all about teamwork, tactics, and fast-paced action.' FROM games WHERE igdb_id = 3076 ON CONFLICT (game_id, language_code) DO NOTHING;
