INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('stronghold-hd', 86652, '2012-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2dr3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhbt.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stronghold HD', 'The original castle sim, Stronghold HD allows you to design, build and destroy historical castles. Engage in medieval warfare against the AI in one of two single player campaigns or online with up to 8 players. With 21 missions to test your mettle and four renegade lords to defeat, it is up to you to reunite medieval England and take back your lands from the treacherous Rat, Pig, Snake and Wolf. Missions range from breaking sieges and capturing enemy castles to raising gold and holding off enemy attacks. Also featured is a full economic campaign, tasking players to gather resources and build weapons within the time limit. Wield greater control over your army than ever before with new high resolution graphics! The new HD battlefield view allows you to zoom out and play in real-time, with the whole map on one screen. Advance on the castle gates while flanking the enemy from behind, feign retreat and lead your foe into a deadly trap or just sit back and watch the destruction unfold.' FROM games WHERE igdb_id = 86652 ON CONFLICT (game_id, language_code) DO NOTHING;
