INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('mdk-2-hd', 29768, '2012-07-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1lob.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arl03.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MDK 2 HD', 'Overhaul Games brings MDK2 back to the PC in incredible high definition, with enhanced graphics, sound, and gameplay. See the classic action platformer the way it was meant to be seen, heard, and played... on a PC! Kurt Hectic in his snazzy suit with ribbon chute is back to save the universe. This time he is teamed with the genius Dr. Hawkins and the 6-legged gun-toting robotic dog, Max. Together they must out-sneak, out-blast and out-think their enemies as they attempt to reclaim the Earth from a vile alien menace. And this time they''re in HD. All three characters - Kurt, Doctor Hawkins and Max are playable, each has his own levels, powers and items and a completely different gameplay focus. Kurt is about stealth and sniping, the Doctor has a few direct attacks but also has the ability to create items and effects out of simple household objects, while Max is a cigar smoking, quad gun toting demolition squad of a dog. Key Features 10 Levels Over 20 Enemies Three different player characters, Max, Dr Hawkins and Kurt Unique levels and items for each character Brand new HD graphics Enhanced audio from the original sources Tweaked gameplay - now Easy really is Easy, while Hard is BONE CRUSHING!' FROM games WHERE igdb_id = 29768 ON CONFLICT (game_id, language_code) DO NOTHING;
