INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Tennis Open', 'Instantly jump into the multiplayer fun, locally or online, as your Mii or your favorite Mushroom Kingdom character. Discover simple touch screen controls as well as strategic depth with different tennis swings, both which propel the tennis experience into an ever-intensifying crescendo of fun as the volleys go on.' FROM games WHERE igdb_id = 5712 ON CONFLICT (game_id, language_code) DO NOTHING;
