INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dragon-ball-z-for-kinect', 2575, '2012-09-25', 47, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co228v.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/onqzucm6geitcban3cbc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball Z For Kinect', 'Dragon Ball Z for Kinect used the unique gameplay abilities of the Kinect motion sensor to let gamers become part of the DBZ world. It features all the classic action and intensity of the Dragon Ball Z universe but with the unprecedented sense of immersion that only Kinect can deliver. Players will be able to unleash over 100 moves upon their enemies, including the legendary Kamehameha, with their very own fists as they battle their way to victory in this ultimate evolution of the unstoppable franchise. Dragon Ball Z For Kinect also packs a double dose of exclusive content for Dragon Ball Z fans! The game includes the Dragon Ball Z anime episode "Episode of Bardock" and will feature Bardock Super Saiyan as a playable character for the first time ever in the history of Dragon Ball Z video games.' FROM games WHERE igdb_id = 2575 ON CONFLICT (game_id, language_code) DO NOTHING;
