INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('midnight-mysteries-4-haunted-houdini', 10548, '2012-03-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4gxf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/yhytyp7gp5sy9lt8gkcc.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Mysteries 4: Haunted Houdini', 'Famed illusionist Harry Houdini knew he wouldn’t escape death forever. When he promised his wife that he would try to reach her from the afterlife, it was seen as the ultimate stunt But after years of séances, Bess was never able to reach Harry in this life or the next, and her spirit has come to you in a final plea to reunite her with her partner! Digging deeper into Houdini’s past, you’ll find bitter rivalries and interview Harry’s closest friends and his staunchest critics. Consult famous friends like Sir Arthur Conan Doyle and rival Thurston the magician, while you solve puzzles and track Houdini’s ties to a super secret society. Help Bess and Harry reconnect in Midnight Mysteries: Haunted Houdini!' FROM games WHERE igdb_id = 10548 ON CONFLICT (game_id, language_code) DO NOTHING;
