INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('nike-plus-kinect-training', 21010, '2012-11-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co22tn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sceh5u.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nike+ Kinect Training', 'Get fitter, faster and stronger with Nike+ Kinect Training, a personalized training experience built from the ground up with athletic expertise and inspiration from Nike coupled with powerful and precise technology from Kinect for Xbox 360. Nike+ Kinect Training brings world-class Nike training directly into the home to help individuals meet their fitness goals and reach their personal best. Through the magic of Kinect, Nike+ Kinect Training can see how the body moves, assess physical strength and athleticism, identify areas for improvement, and create a personalized workout plan tailored to each person. With real-time feedback to make sure positions and movements are correct and a customized program that evolves over time, Nike+ Kinect Training is for everybody, whether a professional athlete, an everyday athlete or someone just getting started. With fitness assessments every four weeks and the ability to work out with friends over Xbox LIVE and tap into the Nike+ community, Nike+ Kinect Training helps athletes stay motivated every step of the way.1 Take training even further by competing in challenges, sending encouragement to friends and keeping workouts on track with a mobile companion app.' FROM games WHERE igdb_id = 21010 ON CONFLICT (game_id, language_code) DO NOTHING;
