INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sleeping Dogs', 'Wei Shen, an young officer working for the San Francisco Police Department gets tasked to go back to his hometown of Hong Kong. In Hong Kong Wei is assigned to the Hong Kong Police Department, in a effort to take down the "Sun on Yee" Wei goes undercover in the triad to gather information and take them down, But the police soon become worried that he is getting attached to his "Friends" such as Jackie Ma. In this journey of Betrayal and High stakes, Will Wei become a "Red Pole" and join the high ranks of the Triads or be discovered by them and buried alive?' FROM games WHERE igdb_id = 1267 ON CONFLICT (game_id, language_code) DO NOTHING;
