INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gravity Rush', 'Gain a new perspective as you take on the role of Kat, a strong-willed girl seeking the means to protect her future in a world that’s crumbling to pieces. Tilt and move the PlayStation Vita System, taking gravity into your own hands to deliver devastating attacks, uncover the secrets to your past and explore a mysterious world.' FROM games WHERE igdb_id = 11701 ON CONFLICT (game_id, language_code) DO NOTHING;
