INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Contract Killer 2: Shadow Conspiracy', 'You are Jack Griffin, the ultimate Contract Killer. Experience an intense, international storyline combining long-range kill shots and close-range melee attacks. To survive in this line of work, you have to sneak your way in, shoot your way out!' FROM games WHERE igdb_id = 63917 ON CONFLICT (game_id, language_code) DO NOTHING;
