INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 Race Stars', 'Get ready to experience Formula One cars, teams and circuits like never before with F1 Race Stars from Codemasters Racing, the home of the series of HD official Formula One games. F1 Race Stars is a fast-to-the-fun arcade racing game featuring the official cars, teams and circuits as they''ve never been seen before. Drivers including Lewis Hamilton, Fernando Alonso and Sebastian Vettel have been transformed into personality-packed heroes bursting with charm and character and stunning Formula One locations have become exhilarating racing theme parks designed for speed and wheel-to-wheel competition.' FROM games WHERE igdb_id = 5311 ON CONFLICT (game_id, language_code) DO NOTHING;
