INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Princess: My Fairytale Adventure', 'Enter the enchanting worlds of Cinderella, Rapunzel, Ariel, Belle and Tiana, and use their magic wand to help undo a spell that''s been cast over the kingdom in Disney Princess: My Fairytale Adventure. Customize your avatar, outfits, accessories, castle and more as you go on an exciting journey filled with quests, dancing, gardening, decorating, familiar characters and more!' FROM games WHERE igdb_id = 36228 ON CONFLICT (game_id, language_code) DO NOTHING;
