INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abobo''s Big Adventure', 'Abobo''s Big Adventure is a freeware parody Flash game. Inspired by various video games released for the Nintendo Entertainment System, the game features Abobo, a boss character from the Double Dragon franchise, traveling through the worlds of several different games to save his son. Developed by I-Mockery founder Roger Barr, Abobo''s Big Adventure was released in January 2012 to positive critical reception.' FROM games WHERE igdb_id = 8735 ON CONFLICT (game_id, language_code) DO NOTHING;
