INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marvel Avengers: Battle for Earth', 'The Skrulls have landed and now it is up to you to embody your favorite Marvel super heroes and defeat epic enemies during the Secret Invasion. Unleash your inner superhero in Marvel Avengers Battle For Earth! The ultimate super hero brawler, Marvel Avengers Battle For Earth features 20 different characters including the Avengers Iron Man, Hulk, Captain America, and Thor, as well as other fan favorite super heroes and villains from the Marvel Universe. Players will use motion gameplay to execute explosive super attacks, unleash devastating special moves, and battle their friends in a wide variety of game modes' FROM games WHERE igdb_id = 5315 ON CONFLICT (game_id, language_code) DO NOTHING;
