INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry', 'An HD remaster of Devil May Cry, first made available in "Devil May Cry HD Collection." In the first installment of the Devil May Cry series, the player controls Dante as he faces off against the resurrected Demon Emperor, Mundus. The game introduces Dante''s abilities, like Devil Trigger which transforms him into a demon, swordplay, gun-slinging, and stylish combos, all of which have become a staple of the series.' FROM games WHERE igdb_id = 222654 ON CONFLICT (game_id, language_code) DO NOTHING;
