INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('they-bleed-pixels', 10988, '2012-08-29', 80, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2l3w.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arcx1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'They Bleed Pixels', 'They Bleed Pixels is a fiendishly difficult action platformer inspired by H.P. Lovecraft and classic horror. Rendered in a distinct visual style that blends pixel art with paper and ink textures, They Bleed Pixels is a singular mix of intense platforming and fierce beat-em-up action. At the core of its fighting system is a simple one-button combat scheme with surprising depth and versatility. Button mashing is discouraged while kicking shadowy monsters into saws, pits and spikes is rewarded, thanks to a unique system that lets you earn and place your own checkpoints through stylish kills. The fancier your kills, the faster you fill the checkpoint meter.' FROM games WHERE igdb_id = 10988 ON CONFLICT (game_id, language_code) DO NOTHING;
