INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dark Arcana: The Carnival', 'Find the missing woman lost in a mysterious Carnival of Horrors. Investigate two worlds: the one you know and an alternate plane existing behind the Hall of Mirrors. Discover the secret of an ancient being known as the Evil One. Reveal the story of star-crossed lovers and stop the Evil One from breaking its magical chains and invading our world. While traveling through dimensions, you will solve cleverly designed minigames and find hidden objects or play a special minigame as an alternative. Best of all, you will befriend a cute and clever monkey devoted to aiding you on this adventure.' FROM games WHERE igdb_id = 10137 ON CONFLICT (game_id, language_code) DO NOTHING;
