INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jack Keane 2: The Fire Within', 'Jack Keane 2 - The Fire Within is set to revolutionise the classic point & click adventure genre. Never has an adventure been as cinematic, fast-paced and humorous, without breaking any of the iconic point & click gameplay rules. State of the art 3D-graphics, gripping action-sequences and the typical bizarre Jack Keanesque humour will be an absolute delight to all adventure fans.' FROM games WHERE igdb_id = 10464 ON CONFLICT (game_id, language_code) DO NOTHING;
