INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ESPN Sports Connection', 'ESPN Sports Connection lets family and friends connect and play the most popular sports from a new perspective. Developed specifically for Nintendo''s Wii U system to take full advantage of its unique tablet controller, the game lets gamers play solo, team up in co-op to experience new gameplay possibilities, or compete in multiplayer challenges in events that cross six popular sports: soccer, football, baseball, tennis, golf, and karting.' FROM games WHERE igdb_id = 28334 ON CONFLICT (game_id, language_code) DO NOTHING;
