INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Corpse Party: Sweet Sachiko''s Hysteric Birthday Bash', 'Corpse Party: Sweet Sachiko''s Hysteric Birthday Bash is a different type of adventure in the Corpse Party series that stars the violent and murderous Sachiko Shinozaki, who has decided to invite her victims to Heavenly Host Elementary School to celebrate her birthday. However, this isn’t the type of party where the guests leave with a smile on their faces. Instead, Sachiko plans to force the students to participate in twisted games for her amusement. Will the students survive Sachiko’s celebration, or will they meet a Wrong End once again?' FROM games WHERE igdb_id = 116560 ON CONFLICT (game_id, language_code) DO NOTHING;
