INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zero Escape: Virtue''s Last Reward', 'The second game in the Zero Escape series. Zero Escape: Virtue''s Last Reward is a mystery/thriller visual novel. It is story focused with multiple endings that use player choices and puzzle rooms to progress. Additions to the game include an ''auto-advance text'' mode, so players can listen to the voice acting without clicking through dialog, a memo function that allows players to note anything they feel is useful, and a flow chart that shows how alternate choices unfold. The in-game calculator has been removed.' FROM games WHERE igdb_id = 6614 ON CONFLICT (game_id, language_code) DO NOTHING;
