INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Paper Mario: Sticker Star', 'A sticky situation has never been so fun! There''s trouble afoot in the town of Decalburg, where the devious Bowser has disrupted the beloved Sticker Fest by causing the Sticker Comet to explode. Now Royal Stickers and pieces of the comet have been flung far and wide, and it''s up to Mario and his ally Kersti to set things right by recovering them. This captivating hand-held adventure will have new and experienced fans of the Paper Mario series captivated as they navigate colorful 3D environments, defeat enemies, collect oodles of stickers and items and use them in a variety of fun ways.' FROM games WHERE igdb_id = 3350 ON CONFLICT (game_id, language_code) DO NOTHING;
