INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('2-fast-4-gnomz', 8618, '2012-02-23', 53, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7n08.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1hzs.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2 Fast 4 Gnomz', '"In this colorful arcade platform runner you will swoosh, spring, and swoop through over a hundred challenging courses. Think fast, tap faster – avoid devious traps, find the best route, and collect all the magical socks on your way to the finish line. Geki Yaba Runner tells a tale of the speedster gnomes on a quest to collect magic socks, save all the princesses, slay all the dragons, and… Well, that might just be a gnome fairytale, but the socks and the speed part is true, we swear! Answer the challenge of the magical kingdom, conquer the hardest racing tracks, laugh at danger (ha, ha!), and become the supreme gnomish speedster in Geki Yaba Runner, free on App Store and Google Play!"' FROM games WHERE igdb_id = 8618 ON CONFLICT (game_id, language_code) DO NOTHING;
