INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tales from Space: Mutant Blobs Attack', 'Tales from Space: Mutant Blobs Attack is a sci-fi puzzle-platformer of cataclysmic proportions. You''re a Blob of alien origin with mutant powers and an insatiable appetite. To the great horror of your former captors (and all of humanity), you have escaped into the world.' FROM games WHERE igdb_id = 5893 ON CONFLICT (game_id, language_code) DO NOTHING;
