INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('street-fighter-x-mega-man', 45184, '2012-12-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6883.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9gcg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Street Fighter X Mega Man', 'Having fought countless Robot Masters over the years, Mega Man is ready to lay back, relax and enjoy his 25th Anniversary. Getting wind of this, Ryu and his fellow Street Fighters want one last battle before they let their own anniversary finish. Charge up your Mega Buster and stretch out your lightning legs, this is Street Fighter X Mega Man! A true collaboration between Capcom and its fans for Mega Man’s and Street Fighter’s 25th Anniversary, Street Fighter x Mega Man was created and developed by Singapore native Seow Zong Hui, with an original soundtrack by Luke Esquivel, and with support provided Capcom, Street Fighter X Mega Man stars the Blue Bomber as he goes toe-to-toe with some of Street Fighter’s most beloved characters complete with their own individual themed stages and boss battles. Jump, shoot, and use your special new Street Fighter abilities to defeat your foes and become the world’s strongest robot!' FROM games WHERE igdb_id = 45184 ON CONFLICT (game_id, language_code) DO NOTHING;
