INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lost-chronicles-of-zerzura', 17559, '2012-02-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9fhq.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/fhznek09mbbjj5s9rdxl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Chronicles of Zerzura', 'Join a young inventor on the expedition of his life. A remarkable journey from Spain, across the Mediterranean, to distant Africa; a quest to save his own soul and lives of those he holds most dear. Two brothers operate a workshop that is well ahead of its time in Barcelona of 1514. It''s the time of the golden epoch of the Renaissance, a time of discoveries and inventions; but also the brutal age of the Inquisition. One brother puts all his efforts into building a flying machine, while the other dreams of Egypt and mysterious art treasures. The advanced ideas and exotic fantasies weaved by the pair arouses the suspicions of the Grand Inquisitor. Quite suddenly their small world is turned upside down as one brother is taken away by the Inquisition; leaving the other alone to search for answers that will set his imprisoned sibling free. Explore the ravishingly beautiful and detailed locations of this remarkable adventure as you become immersed in this mysterious medieval tale and solve a unique combination of puzzles, mini-games, and other challenges that are perfectly integrated within this breathtaking storyline. Evade further attacks by the inquisition, and forge strong alliances with those you meet along the way. Trek across different countries and cultures and eventually to the legendary desert city of ZERZURA, where an ancient terror guards over powerful secrets - and poses the greatest challenge of all.' FROM games WHERE igdb_id = 17559 ON CONFLICT (game_id, language_code) DO NOTHING;
