INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Test Drive: Ferrari Racing Legends', 'Detailed physics underpin a huge variety of challenges set throughout the history of this landmark automotive brand. Painstakingly detailed cars and tracks reflect visceral damage as races wear on, an acute sense of speed communicates the power of these highly tuned vehicles, as advanced AI challenges even the most experienced driver.' FROM games WHERE igdb_id = 7217 ON CONFLICT (game_id, language_code) DO NOTHING;
