INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunar-flight', 10524, '2012-01-15', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4gwp.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lfgmp4nd0ykwiok3bbfo.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunar Flight', 'Explore the most realistic and beautiful realtime simulation of ''Lunar Flight'' in this unique and challenging game. Experience the heart pounding sense of dread as you deliver supplies to moon bases with only seconds of fuel to spare! A modern take on the classic arcade game, Lunar Lander, Lunar Flight extends the experience to a fully fictionalized and accessible lunar module simulator providing a variety of mission types involving transporting cargo, acquiring data at survey locations and locating lost cargo. Completing missions earns experience points and money to be used to refuel, repair and upgrade the lunar module. In addition to missions there are time trial challenges complete with online leader boards and a globally ranked ‘pilots’ leader board, ranked by experience. To round out the game there are a variety of achievements to provide additional challenges and objectives. When you think you''ve got what it takes, head online and go head to head in deadly combat against the best pilots in the world in Lunar Flights Multiplayer mode.' FROM games WHERE igdb_id = 10524 ON CONFLICT (game_id, language_code) DO NOTHING;
