INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-cat-lady', 11270, '2012-12-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rfw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar21mq.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cat Lady', 'Susan Ashworth, known in her neighbourhood as the crazy Cat Lady, is a lonely 40- year old on the verge of suicide. She has no family, no friends and no hope for a better future.One day she discovers that five strangers will come along and change everything.But those five, "The Parasites", are also the most ruthless, deranged and cold-blooded bunch of psychopaths the city has ever known. They will stop at nothing to hurt Susan. Unless, she hurts them first... Susan''s few weeks journey doesn''t take her across the world and won''t turn her into a hero. She has little faith in others and hardly even cares about herself. She can''t fight and has never fired a gun in her life. But she''s hanging onto that thin thread of hope, that in the end, as promised, there''s an elusive reward waiting for her. Something worth trying for. Something that''ll help her find an unlikely friend. Something that''ll give her life a purpose. Susan''s journey takes her on a roller-coaster ride between the world of the living and the world of the dead, where the only way to survive is to overcome her biggest weakness: her own self.' FROM games WHERE igdb_id = 11270 ON CONFLICT (game_id, language_code) DO NOTHING;
