INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dishonored', 'Dishonored is an immersive first-person action game that casts you as a supernatural assassin driven by revenge. With Dishonored’s flexible combat system, creatively eliminate your targets as you combine the supernatural abilities, weapons and unusual gadgets at your disposal. Pursue your enemies under the cover of darkness or ruthlessly attack them head on with weapons drawn. The outcome of each mission plays out based on the choices you make.' FROM games WHERE igdb_id = 533 ON CONFLICT (game_id, language_code) DO NOTHING;
