INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny and Big: Grandpa''s Leftovers', 'Tiny & Big, a comic styled jump and slice platformer, gives you the unique ability to shape a whole world at your will! You are Tiny, a nerdy inventor who tries to reclaim his most beloved possession: Grandpa''s white, fine rib underpants! On his journey through a forsaken desert he will meet mysterious creatures, no clowns, a taxi robot and his arch enemy: Big!' FROM games WHERE igdb_id = 3079 ON CONFLICT (game_id, language_code) DO NOTHING;
