INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'R.A.W: Realms of Ancient War', 'In this explosive Hack''n''Slash action/role-playing game, R.A.W takes you, alone or with a friend in co-operative mode, on a fantasy world ruined by an ancient and violent war. Level your heroes up, collect more powerful weapons and armor, unlock new and more devastating spells, and exterminate by the dozens at once the hordes of enemies that are standing in your way.' FROM games WHERE igdb_id = 10753 ON CONFLICT (game_id, language_code) DO NOTHING;
