INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Triple Town', 'Triple Town is an original puzzle game in which you try to grow the greatest possible city. The larger the city you build, the more points you score. You build your city by matching three or more game-pieces: combine three grasses to make a bush, three bushes to make a tree... until you''ve filled the board with houses, cathedrals and castles. Along the way, you''ll have to outwit giant bears who will try to block your progress.' FROM games WHERE igdb_id = 14405 ON CONFLICT (game_id, language_code) DO NOTHING;
