INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anomaly-korea', 8760, '2012-12-20', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rkw.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar51qf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anomaly Korea', 'Anomaly Korea is an expansion campaign to Anomaly Warzone Earth. The alien robots are back and this time they’ve got Korea in their sights. It’s your job to lead a squad into fierce fire-fights and fend off the alien invasion. Plan your routes carefully and use new units and powers to turn the tide of war against a horde of new enemy threat. THIS ISN''T TOWER DEFENSE IT''S TOWER OFFENSE. Flipping the tower defense genre on its head, you play the invaders leading your unit into alien-infested districts. Plan carefully, use your money and powers wisely, and make it through unscathed. A NEW WAY TO PLAY Keep an eye on the action from a top-down perspective, assemble your squad, plan your route using the tactical map and simply execute player powers such as Boost, which speeds up your unit’s offense. Test your leadership abilities in the extra ‘Art of War’ trials.' FROM games WHERE igdb_id = 8760 ON CONFLICT (game_id, language_code) DO NOTHING;
