INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubemen', 'Cubemen is a fast paced, action packed, original 3D Tower Defense game that mixes TD with RTS in single player & online multi-­player awesomeness! Get ready for some crazy Cubemen action! It’s the age old struggle between Good vs Bad, Blue vs Red, Little men vs Little men. Use your own little Cubemen to defend your base from other little Cubemen that are trying to run it over. It’s the usual story, but with many very interesting twists.' FROM games WHERE igdb_id = 16346 ON CONFLICT (game_id, language_code) DO NOTHING;
