INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Valley Without Wind', 'A Valley Without Wind is a indie and action-adventure video game developed by Arcen Games. The game was released on April 24, 2012 for the operating systems Microsoft Windows and Mac OS X on Steam. Players play as a random survivor in an unforgiving world that is shaped by the choices the player makes. The setting of the game is a post-ice-age world in the distant future.' FROM games WHERE igdb_id = 1625 ON CONFLICT (game_id, language_code) DO NOTHING;
