INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('microsoft-minesweeper--1', 127494, '2012-07-27', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1v32.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar19hl.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Minesweeper', 'Featuring adjustable difficulty, classic Minesweeper gameplay, and a brand new Adventure mode, Microsoft Minesweeper is better than ever. Classic Mode Play the logic game you know and love, now with updated graphics and sound. Play with a touch screen or with a mouse and keyboard to mark the locations of all the mines without uncovering any of them! Start with an Easy puzzle and work your way up to Expert. Adventure Mode Players who want a different kind of challenge can try this brand new game mode! Use your skills in Adventure mode to guide your brave hero to the center of Earth, collecting riches along the way. Blending traditional Minesweeper rules with fun new goals, Adventure Mode is a fresh take on a classic! Daily Challenges Players receive new Challenges every day. Complete them to earn prizes and compete with your friends!' FROM games WHERE igdb_id = 127494 ON CONFLICT (game_id, language_code) DO NOTHING;
