INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('hell-yeah-wrath-of-the-dead-rabbit', 5618, '2012-09-25', 74, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2fd3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arfpa.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hell Yeah! Wrath of the Dead Rabbit', 'Ash, a skeletal rabbit and the prince of Hell, has inherited the role of ruler of Hell from his father. After a photographer takes a picture of Ash playing with a rubber duck in the bathtub, Ash sets out to kill the 100 monsters that have seen the photo, to restore his image. The world of Hell Yeah! Wrath of the Dead Rabbit has several zones with different visual styles, including "haunted caves, science labs, casinos and spaceships full of talking animals". The player navigates these zones by traveling on a large buzz-saw-like circular blade that can cut through the environment, can fire a variety of projectile weapons, and is equipped with a jetpack. Ash is assisted in his quest by his butler, Nestor, a top hat-wearing Octopus.' FROM games WHERE igdb_id = 5618 ON CONFLICT (game_id, language_code) DO NOTHING;
