INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jagged Alliance: Back in Action', 'Designed from the ground up to offer a modern gaming experience, "Back in Action" showcases an updated isometric 3D look and interface, highly detailed character models and a variety of new gameplay features. "Back in Action" takes players to the fictitious country of Arulco, where a ruthless dictator has seized power and only a small group of rebels stand to resist him. Tasked with freeing the island from the dictator''s iron grip, players will command rebel and mercenary forces while using tactical, diplomatic and economic tools to keep troops supplied and ready for the next flight, all while commanding them directly in nail-biting battles.' FROM games WHERE igdb_id = 1008 ON CONFLICT (game_id, language_code) DO NOTHING;
