INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chompy Chomp Chomp', 'Chompy Chomp Chomp is a maze-based multiplayer rampage in which Chompies chase each other around trying to eat their target colour Chompy. Underneath your Chompy''s feet you have a target the colour of the Chompy you need to eat. You get points for chomping, you lose points for being chomped. The target colours change at random, turning hunters into hunted and vice versa.' FROM games WHERE igdb_id = 8425 ON CONFLICT (game_id, language_code) DO NOTHING;
