INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mad Riders', 'FEEL THE HEART-POUNDING THRILL OF EXTREME OFF-ROAD RACING COMPETITION  Perform aerial stunts, use your boost wisely, and open shortcuts to dominate your friends on 45 tracks in stunning tropical locations across the globe.  The game’s breathtaking speed and accessible gameplay allows players of all skills to instantly pick up on the fun, while the competitive multiplayer and customization options will keep them coming back.' FROM games WHERE igdb_id = 8035 ON CONFLICT (game_id, language_code) DO NOTHING;
