INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Agency', 'Space Agency is a lightweight rocket-building and space mission simulator. Design rockets, build satellites, establish space stations, and plan missions across the solar system—all with a modular building system and basic orbital physics. It offers multiple game modes, including tutorials, career-style mission progression, quick play, and sandbox. It''s designed for accessibility rather than realism, offering modular craft-building, mission-based progression, and sandbox creativity.' FROM games WHERE igdb_id = 87721 ON CONFLICT (game_id, language_code) DO NOTHING;
