INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-witcher-2-assassins-of-kings-dark-edition', 22319, '2012-04-17', 90, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2lgr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/n3t1e4m2hsuy7qmc2wnk.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Witcher 2: Assassins of Kings - Dark Edition', 'Compared to the initial award winning PC release, the Xbox 360 edition will feature lots of new and exciting content. Additional hours of gameplay for the Xbox 360: New major adventures set in previously unseen locations, expanding the story and introducing new characters, mysteries and monsters. New Game Introduction and cinematic: All new animations and cut scenes, including a new, three and a half minute pre-rendered cinematic depicting the assassination of King Demavend of Aedirn. BAFTA Award winner and Academy Award nominee Tomasz Baginski brings this key historical event to life, setting the stage for the story told in The Witcher 2. Upgraded interface, designed specifically for the Xbox 360: Game camera and targeting have been redesigned for the Xbox, and with upgraded pad controls, players will now be able to experience fully The Witcher 2''s spectacular and thrilling combat. Dark Edition content: The Witcher 2: Assassins of Kings game on 2 DVDs, MAKING-OF DVD: All the cinematic materials related to game - trailers, dev diaries, gameplay footage, interviews and making-of exclusive video. WORLD MAP: A map of the game''s world. THE WITCHER MEDALLION: A wolf head metal medallion on a chain. QUEST HANDBOOK: The Witcher 2 quest handbook for both novice and experienced role-playing fans. GAME MANUAL: A rulebook and interface explanation to help you get started. ARTBOOK: Extensive, 232 pages documentary of game''s graphical assets with descriptions. Including concept arts, cover renders and stories behind Art of The Witcher 2. STICKERS: Three stickers with Witcher 2 graphics. DARK EDITION BOX: An elegant thick cardboard box to hold all your valuable Dark Edition contents.' FROM games WHERE igdb_id = 22319 ON CONFLICT (game_id, language_code) DO NOTHING;
