INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Juniors', 'The LEGO Juniors app is an engaging, creative building game for children ages 4-7, with lots of opportunities to practice creative problem-solving. With every new LEGO vehicle your child builds, they can cruise around LEGO landscapes as minifigure avatars like mechanics, princesses, pilots – and even LEGO Batman. The goal is to turn the open landscapes into busy neighborhoods by unlocking and building virtual houses and decorations.' FROM games WHERE igdb_id = 88873 ON CONFLICT (game_id, language_code) DO NOTHING;
