INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Papa''s Hot Doggeria', 'Papa''s Hot Doggeria is a home run! It''s opening day at Griller Stadium but the season tickets are all sold out! Looks like the only way to watch the games is to work for your old pal Papa Louie. In Papa''s Hot Doggeria you''ll need to grill up juicy Hot Dogs, top them with a variety of condiments, and serve them to all the rowdy fans. You''ll also have your hands full popping up fresh popcorn, and pouring a crazy amount of drinks for your hungry customers. Meet all new faces, cheer on your favorite team, and even take a swing in the Home Run Derby!' FROM games WHERE igdb_id = 210491 ON CONFLICT (game_id, language_code) DO NOTHING;
