INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BasketBelle', 'BasketBelle is an experimental 2D basketball-based platformer. Each Chapter of the game uses the mechanics and idea of basketball in a different way. At one point you might be dribbling inside the intestines of a purple blob creature (what?). At others, you''re likely to be dunking above the clouds in front of the Parisian moon.' FROM games WHERE igdb_id = 14766 ON CONFLICT (game_id, language_code) DO NOTHING;
