INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'War of the Roses', 'War of the Roses: Kingmaker is a team based third person action game set in 15th century England. Two rival branches of the Royal House of Plantagenet - the house of Lancaster (the reds) and the house of York (the whites) - it''s a fight for the throne, and the player is thrown into the fray.' FROM games WHERE igdb_id = 1385 ON CONFLICT (game_id, language_code) DO NOTHING;
