INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Forza Horizon', 'Forza Horizon is an action racing game set on the epic open roads of Colorado with a thrilling music festival backdrop. Combining stunning graphics and cutting-edge music with legendary Forza authenticity and a superb collection of cars to drive, Forza Horizon is an open-world automotive playground that puts a spotlight on speed, style, and the freedom of the open road. This is where cars belong!' FROM games WHERE igdb_id = 3047 ON CONFLICT (game_id, language_code) DO NOTHING;
