INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Dash', 'Mini Dash is a 2D fast-paced platforming game from PlayCreek LLC. Mini Dash is a frenetic, fun, fast platformer that oozes quality. Full of ideas and unexpected turns, it will have you hooked the moment you tap its beautifully formed icon! Take control of our hero and dash into the trap-filled worlds of Mini Dash. It''s the classic left, right, jump controls but it a world turned, literally, on its head! Loads of inventive levels are served up each challenging you to find the exit - sounds simple until you factor in the deadly dashing hazards that litter the landscape.' FROM games WHERE igdb_id = 61052 ON CONFLICT (game_id, language_code) DO NOTHING;
