INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amoebattle', 'Built from the ground up, Amoebattle delivers a portable twist to the real time strategy genre and brings the experience to the palm of your hand. Intuitively command your troops using the Touch Screen as you discover interesting types of amoebas, journey through fantastic environments, and lead your amoebas to victory in battle…Amoebattle!' FROM games WHERE igdb_id = 21733 ON CONFLICT (game_id, language_code) DO NOTHING;
