INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8bit Ninja', 'Meet 8bit the little ninja and help him avoid the angry crowd''s fruit attack! In this juicy ninja game, your goal is to survive as long as possible while avoiding waves of melons, coconuts, oranges, lemons and the ultra rare dragon fruits! Use your ninja weapons to blow the fruits into tasty pieces! 8bit is not alone in his quest, meet his friends each with unique abilities!' FROM games WHERE igdb_id = 232005 ON CONFLICT (game_id, language_code) DO NOTHING;
