INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a-men', 8623, '2012-02-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6007.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/utkxnja3vsothqcba1ku.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A-Men', 'What is A-Men? Classic puzzle-platformer, inspired by some oldschool titles like Lemmings and Lost Vikings. What is A-Men like? Hard. No holding your hand, no easy levels, we want to challenge you. If you are a casual, A-Men is not for you.Key features:Hardcore puzzle-platformer, that will make you cry, if you aren''t good enough40 levels, that will give you a challengeHigh replay value - beat your best score and get all the achievementsPretty graphics, with a retro touchFive characters, with different skills and abilitiesThey played A-MenLooking for gameplay videos of A-Men? We got them here! BRBteabreakTV - English Jimmy Dali - English DarykonLP - German Want us to add your video here? Let us know!Review our game Are you a youtuber, blogger or just an editor at the gaming site, that wants to review our game? Drop us an email at press@blooberteam.com and we''ll help you with that. Small, big, doesn''t matter, everyone is welcome! Feel free to monetize!Any questions, feedback or problems?Visit our community and let us know!Stay updatedFollow us on Facebook and Twitter for all the updates about our games!' FROM games WHERE igdb_id = 8623 ON CONFLICT (game_id, language_code) DO NOTHING;
