INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legasista', 'Legasista is a PlayStation 3 game published by Nippon Ichi Software. It was released in Japan on disc in March 2012 then in North America and Europe exclusively as a downloadable game through the PlayStation Network in August 2012. It is a dungeon crawling action role-playing game. For the game''s North American and European releases, it was not dubbed, spoken dialog remaining in the original Japanese.' FROM games WHERE igdb_id = 20881 ON CONFLICT (game_id, language_code) DO NOTHING;
