INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncharted 3: Drake''s Deception - Game of the Year Edition', 'A Game of the Year Edition of Uncharted 3 was released on September 21, 2012, in Europe, with no mention of a release outside of Europe. However, the edition was released in North America on September 25, 2012, as part of a gaming bundle of the 250GB version of the slimmer PlayStation 3. This edition included all previously released DLC (up to 14 pieces of content in total), which was previously available as part of the "Uncharted 3 Fortune Hunters'' Club". In addition to Uncharted 3: Drake''s Deception, this also includes: - Multiplayer maps (Graveyard, Old Quarter, London Streets, Oasis) - "Flashback maps" which are 8 remade maps from versions 1 and 2 - 25 multiplayer skins, and Killzone 3 skins - Fort Co-Op (this happens in the fortress from ''Drake''s Fortune'') - Rogue skins pack (from 14 enemies)' FROM games WHERE igdb_id = 41884 ON CONFLICT (game_id, language_code) DO NOTHING;
