INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dead-island-game-of-the-year-edition', 47400, '2012-06-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co60hd.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmf5d.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Island: Game of the Year Edition', 'A tropical island resort becomes a place of nightmares after a mysterious epidemic turns the majority of inhabitants into bloodthirsty zombies. As one of four playable characters, your goal is to complete missions necessary for your survival, which means battling throngs of the undead with a variety of customizable weapons and finding a way off the fictitious island of Banoi. Dead Island features an open-world environment in a campaign that supports up to four players for drop-in, drop-out cooperative action. The two male and two female characters have different strengths and weaknesses, which can be offset to a degree by leveling up. Experience points earned in combat can be used to improve a character''s attributes and fighting skills. When firearms and ammo are in limited supply, you''ll be able to engage enemies in hand-to-hand combat with axes, machetes, knives, clubs, and similar edged or bludgeoning weapons that will degrade over time. Explore the island''s urban areas, forests, mountain highlands, caves, beaches, and other locales from a first-person perspective, or utilize an over-the-shoulder view for melee combat. The "Game of the Year Edition" for Xbox 360 includes new blueprints and weapons, the original Dead Island, and its two main DLC releases: the multiplayer "Bloodbath Arena" and the single-player "Ryder White" campaign.' FROM games WHERE igdb_id = 47400 ON CONFLICT (game_id, language_code) DO NOTHING;
