INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Monday Night Combat', 'Super Monday Night Combat is a free to play, strategic, multiplayer shooter… and the most popular lethal sport of the future! It blends intense tactical combat, a deep metagame, an ever-expanding roster of Pros, and an ever-growing amount of customizations. Why fight in bombed out cities or desert wastelands when you can have every kill streak judged by hilarious sportscasters and cheering, or jeering, fans' FROM games WHERE igdb_id = 16255 ON CONFLICT (game_id, language_code) DO NOTHING;
