INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sing Party', 'Party All Night Long Get the party started with SiNG Party, a new, interactive musical performance game that will get you and your guests singing and dancing well into the night. With dozens of popular songs to choose from, everyone from novice singers to experienced entertainers will be able to join in the fun. While one person steps up as the main performer, others can dance, sing and clap along with the prompts on the TV screen, making sure everyone at the party is rocking out together.' FROM games WHERE igdb_id = 3108 ON CONFLICT (game_id, language_code) DO NOTHING;
