INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SimCity Social', 'SimCity Social is a city-building simulation game available on Facebook. SimCity Social brings the real city-building simulation to the masses, giving players the freedom to create sprawling cities that come to life as a result of player-driven choice. In SimCity Social, players don’t just build a city – they choose the kind of city they want and watch its soul come to life as it grows and reacts to their decisions.' FROM games WHERE igdb_id = 64978 ON CONFLICT (game_id, language_code) DO NOTHING;
