INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Shall Remain', 'An Action RPG at its core, I Shall Remain combines role-playing elements with survival and strategic aspects, and creates a blend never before seen. Through complex, real-time character progression and RPG system, over a hundred abilities to learn and upgrade, dozens of weapons and enhancers, thousands of Infected, over twenty mutations, tens of NPCs and teammates, within a twenty-plus hour long story campaign, ISR offers plenty for everybody.' FROM games WHERE igdb_id = 17234 ON CONFLICT (game_id, language_code) DO NOTHING;
