INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doom 3', 'The 2004-era Doom 3 with enhanced graphics, a checkpoint save system, 3D Capability for 3D Televisions and Achievements/Trophies (Xbox 360, Steam, and PS3). Unlike the original game which featured the Flashlight as a ''weapon'' itself, the BFG Edition instead was ''armor-mounted'' meaning players can attack and illuminate dark areas simultaneously. It was released inside Doom 3: BFG Edition.' FROM games WHERE igdb_id = 260028 ON CONFLICT (game_id, language_code) DO NOTHING;
