INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bloons-td-5-hd', 88911, '2012-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/x1ejalhtm164yhlssfhg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/slrtr3t3zagmknitngzj.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloons TD 5 HD', 'Five-star tower defense with unrivaled depth and replayability. Now with rewarded leaderboards for even more fun and challenge! The Bloons are back in full HD glory and this time they mean business! Build awesome towers, choose your favorite upgrades, hire cool new Special Agents, and pop every last invading Bloon in the best ever version of the most popular tower defense series in history. Featuring 2 brand new Towers, cool Special Agents, glorious retina graphics, original Tracks and Special Missions, a whole new tier of Specialty Building upgrades, and the powerful Monkey Lab to further upgrade your towers, Bloons TD 5 delivers hours and hours of fun, challenging play to fans and new players alike. Hours and Hours of Awesome Gameplay: - 21 powerful towers with Activated Abilities and 2 upgrade paths - 10 Special Agents - 50+ Tracks (plus their Reverse versions!) - 10 Special Missions - 250+ Random Missions - New Bloon enemies - tougher Camos, Regrower Bloons, and the fearsome ZOMG - 50+ Game Center Achievements and Challenges - iCloud Support - 3 different game modes - Freeplay mode after mastering a track - 4 difficulty settings and family-friendly theme so anyone can play And that''s just the beginning - regular updates will keep Bloons TD 5 HD fresh, fun, and challenging for many months to come. Now it''s time to pop some Bloons! Remember to save to iCloud after each victory or purchase to save your progress. Please note the Bloons TD 5 HD is for iPad and iPad mini devices only - it is incompatible with iPhone and iPod touch devices.' FROM games WHERE igdb_id = 88911 ON CONFLICT (game_id, language_code) DO NOTHING;
