INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major League Baseball 2K12', 'Major League Baseball 2K12 or, in short, MLB 2K12, is a Major League Baseball licensed baseball simulation video game published by 2K Sports that was released for the PlayStation 2, PlayStation 3, PlayStation Portable, Microsoft Windows, Nintendo DS, Wii and Xbox 360 on March 6, 2012. The commentary is delivered by the trio of Steve Phillips, Gary Thorne, and John Kruk. Justin Verlander of the Detroit Tigers is the game''s cover athlete.[1] Verlander won both the AL Cy Young Award and the AL MVP Award in 2011.' FROM games WHERE igdb_id = 4993 ON CONFLICT (game_id, language_code) DO NOTHING;
