INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('moviestarplanet', 94981, '2012-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coae9h.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar44la.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MovieStarPlanet', 'MovieStarPlanet is the coolest social network & game for kids! Attention boys and girls! Are you looking for stardom? Then welcome to our planet filled with stars. Create a Movie Star today and make awesome Movies, ArtBooks and photos, and share them with your friends and fans. You might become a famous celebrity overnight. Let your creativity loose! Become the best fashion designer and design your own clothes, play Dress Up and model your creations. Create the most amazing art of all time to earn Fame, get awards and rise to stardom. There is tons of fun waiting for you on MovieStarPlanet! We are a family-oriented game that takes safety SERIOUSLY, and we always work to ensure MovieStarPlanet is a place where parents can trust their kids to hang out. Visit our Help Center https://moviestarplanet.zendesk.com/hc/ Here''s a taste of the fun and cool things you can do on MovieStarPlanet: - Create an Avatar doll of yourself to show off your awesome designs - Make new FRIENDS and CHAT in cool chatrooms - Decorate your own Room - Take care of your own pet & Boonies - Create Looks, Fashion, ArtBooks & Movies using animations and crazy stickers - Design your own clothes and give your Movie Star a makeover - Watch YouTube Videos of your favorite shows and celebrities - Play fun games with other gamers and climb to the top of our Highscores What are you waiting for? Download the MovieStarPlanet mobile app for your phone and tablet. Join the fun online! See more at moviestarplanet.com – the number one site for fame, fortune, fun & friends!' FROM games WHERE igdb_id = 94981 ON CONFLICT (game_id, language_code) DO NOTHING;
