INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Slam Tennis 2', 'Feel the true excitement and emotion of championship tennis with EA SPORTS Grand Slam Tennis 2. For the first time in HD and on the next generation platforms, experience the thrill of winning at Wimbledon and capturing all four Grand Slam tournaments. Rise to stardom with the revolutionary Total Racket Control as you challenge a deep roster of elite players, including Djokovic, Federer, Nadal, Sharapova, Borg, and McEnroe. With immersive PlayStation Move support, authentic gameplay, ESPN broadcast integration, a deep 10-year career mode and so much more, get ready to Swing the racket like a Grand Slam champion with Grand Slam Tennis 2.' FROM games WHERE igdb_id = 7002 ON CONFLICT (game_id, language_code) DO NOTHING;
