INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario & Sonic at the London 2012 Olympic Games: Virtual Card Album', 'Mario & Sonic - London 2012 Virtual Card Album was a free downloadable app associated with Mario & Sonic at the London 2012 Olympic Games that was released in Europe by Nintendo and Sega under license from the International Olympic Committee to correspond with the 2012 London Olympics. When first announced at the June 2012 Nintendo Direct, it was called Mario & Sonic at the London 2012 Olympic Games Virtual Card Album.' FROM games WHERE igdb_id = 294652 ON CONFLICT (game_id, language_code) DO NOTHING;
