INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dirt 3: Complete Edition', 'Dirt 3: Complete Edition includes 2011''s rally racing game as well as four expansion packs previously available as downloadable content. In addition to the Dirt 3 base game, players will receive the following car and track packs: the Monte Carlo Rally Pack, the X Games Asia Track Pack, the Power and Glory Car Pack, and the Mud and Guts Car Pack. Featured vehicles in the bonus content include the Saturn Sky, Ford Mustang GT, Lancia Delta S4, BMW M3 Rally, and Lancia Stratos, among others.' FROM games WHERE igdb_id = 47381 ON CONFLICT (game_id, language_code) DO NOTHING;
