INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Devil May Cry 3: Dante''s Awakening - Special Edition', 'An HD Remaster of Devil May Cry 3: Dante''s Awakening - Special Edition, included in "Devil May Cry HD Collection." Devil May Cry 3 takes place before the events of the first game. In this installment, you can choose different close-combat styles like Swordmaster and Gunslinger, and it''s up to you which style you decide to develop and improve on. This Special Edition lets you play as Dante''s brother Vergil.' FROM games WHERE igdb_id = 222656 ON CONFLICT (game_id, language_code) DO NOTHING;
