INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('oniken', 8963, '2012-06-21', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co26c4.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar5bpr.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oniken', 'When a global war nearly decimated humankind, an evil military organization called Oniken takes advantage of the situation to dominate and oppress the few remaining survivors. Even though any resistance to this organization seemed hopeless, a small rebel movement organizes strikes against Oniken. One day, a ninja mercenary named Zaku offers his services to the resistance for unknown reasons. His moves are lethal and now he is the resistance''s only hope. Oniken is an action platform game highly inspired by the 1980''s, its games and its movies. You can see this not only in the graphics and sound design, but also in Oniken''s story and difficulty. Don''t Worry, You Will Die A Lot Of Times. Every copy of Oniken comes with digital versions of the game manual and the original soundtrack.Features Graphics, sounds and difficulty from the 8-bit era Cinematic cutscenes Over 18 boss fights Six missions, three stages each An extra mission after you beat the game Boss rush mode Not difficult enough? Try the new HARDCORE MODE Global Leaderboards Full pixelated violence' FROM games WHERE igdb_id = 8963 ON CONFLICT (game_id, language_code) DO NOTHING;
