INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Jungle', 'In Tokyo Jungle, everything is the enemy, and only the strongest will survive! With over 50 playable animals to choose from, unleash your inner beast to hunt your way to the top of Tokyo''s post-apocalyptic food chain. Whether in Story or Survival Mode, you never know where your next meal will come from or the dangers you''ll face, so be prepared for anything and everything. Forage through this desolate but dangerous city to complete story-based challenges using a variety of survival skills, from all-out attack to stealth. Beware-- you are not the only animal out there hunting for survival!' FROM games WHERE igdb_id = 7467 ON CONFLICT (game_id, language_code) DO NOTHING;
