INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Skylanders: Giants', 'Skylanders: Giants is a 2012 video game in the Skylanders series, a direct sequel to the 2011 game Skylanders: Spyro''s Adventure and features the voices of Kevin Michael Richardson, Greg Ellis, Peter Lurie, Steve Blum, Dave Wittenberg, Carlos Alazraqui, Kevin Sorbo, Bobcat Goldthwait, Patrick Seitz and Julie Nathanson. It is the game before Skylanders: Swap Force. As the title suggests, it features larger Skylanders known as "Giants", along with other new gameplay mechanics.' FROM games WHERE igdb_id = 1586 ON CONFLICT (game_id, language_code) DO NOTHING;
