INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Babel Rising', 'Babel Rising puts you in the sacred sandals of the great and angry Almighty God. Bring to bear scorching and wrathful powers to smite arrogant humans and prevent them from building the tower of Babel. You shall hurl bolts of holy lightning, summon punishing earthquakes, and unleash vengeful floods upon the foolish and irreverent Humans. This next-gen version of the critically acclaimed iPhone game adds something new to its original gameplay. Thanks to 3D and motion control, player can now enjoy an epic peplum experience.' FROM games WHERE igdb_id = 10017 ON CONFLICT (game_id, language_code) DO NOTHING;
