INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MotorStorm: RC', 'High-speed radio-controlled car racing hits the MotorStorm circuit in MotorStorm RC! With visually stunning renditions of all four MotorStorm worlds (and eight of their vehicle classes,) this RC racing game comes loaded with endless competition that you can share with friends and rivals worldwide -- whether that''s on PS3 or PS Vita, or both!' FROM games WHERE igdb_id = 2556 ON CONFLICT (game_id, language_code) DO NOTHING;
