INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liberation Maiden', 'Liberation Maiden is a shooter game developed by Grasshopper Manufacture and published by Level-5. It was originally included in the Guild01 compilation for the Nintendo 3DS in 2012, and later made available separately on Nintendo eShop. A stand-alone high definition version was also released for the iOS in 2013.' FROM games WHERE igdb_id = 21007 ON CONFLICT (game_id, language_code) DO NOTHING;
