INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Unfinished Swan', 'The Unfinished Swan is a game about exploring the unknown. The player is a young boy chasing after a swan who has wandered off into a surreal, unfinished kingdom. The game begins in a completely white space where players can throw paint to splatter their surroundings and reveal the world around them.' FROM games WHERE igdb_id = 8352 ON CONFLICT (game_id, language_code) DO NOTHING;
