INSERT INTO game_videos (game_id, url, thumbnail_url, title, video_type, display_order, is_featured) SELECT id, 'https://www.youtube.com/watch?v=L8kY6_TqdBI', 'https://img.youtube.com/vi/L8kY6_TqdBI/maxresdefault.jpg', 'Trailer', 'trailer', 0, true FROM games WHERE igdb_id = 2129 ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2129 AND rs.code = 'ESRB' AND r.code = 'M' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2129 AND rs.code = 'PEGI' AND r.code = '16' ON CONFLICT DO NOTHING;
INSERT INTO game_ratings (game_id, rating_id, is_primary) SELECT g.id, r.id, false FROM games g, ratings r JOIN rating_systems rs ON r.rating_system_id = rs.id WHERE g.igdb_id = 2129 AND rs.code = 'CLASS_IND' AND r.code = '14' ON CONFLICT DO NOTHING;
INSERT INTO game_languages (game_id, language_code, language_name, has_audio, has_subtitles, has_interface) SELECT id, 'de', 'German', false, false, true FROM games WHERE igdb_id = 2129 ON CONFLICT DO NOTHING;
